"use client";

import { useState, useRef, useEffect, useCallback } from "react";
import { supabase } from "../lib/supabaseClient";
import { useRouter } from "next/navigation";
import * as pdfjsLib from "pdfjs-dist";

// PDF Worker setup
pdfjsLib.GlobalWorkerOptions.workerSrc = `//unpkg.com/pdfjs-dist@${pdfjsLib.version}/build/pdf.worker.min.mjs`;

export default function Home() {
  const [conversations, setConversations] = useState([]);
  const [activeChat, setActiveChat] = useState(null);
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const [imageLoading, setImageLoading] = useState(false);
  const [user, setUser] = useState(null);

  // Theme State
  const [theme, setTheme] = useState("dark");

  // File Upload States
  const [selectedFile, setSelectedFile] = useState(null);
  const [fileContent, setFileContent] = useState("");
  const [readingFile, setReadingFile] = useState(false);
  const fileInputRef = useRef(null);

  const abortControllerRef = useRef(null);
  const router = useRouter();

  // Auth check & User session load
  useEffect(() => {
    const checkUser = async () => {
      const {
        data: { user },
      } = await supabase.auth.getUser();

      if (!user) {
        router.push("/login");
      } else {
        setUser(user);
        fetchConversations(user.id);
      }
    };
    checkUser();
  }, [router]);

  // Stable Fetch Messages Function
  const fetchMessages = useCallback(async (chatId) => {
    if (!chatId) {
      setMessages([]);
      return;
    }

    console.log("Fetching messages for chat:", chatId);

    const { data, error } = await supabase
      .from("messages")
      .select("*")
      .eq("conversation_id", chatId)
      .order("created_at", { ascending: true });

    if (error) {
      console.error("Error loading messages:", error.message);
      return;
    }

    console.log("Loaded messages:", data);
    if (data) setMessages(data);
  }, []);

  // Automatic Trigger jab bhi activeChat change ho
  useEffect(() => {
    if (activeChat) {
      fetchMessages(activeChat);
    } else {
      setMessages([]);
    }
  }, [activeChat, fetchMessages]);

  // Theme Switcher Handler
  const toggleTheme = () => {
    const nextTheme = theme === "dark" ? "light" : "dark";
    setTheme(nextTheme);
    document.documentElement.setAttribute("data-theme", nextTheme);
  };

  const fetchConversations = async (userId) => {
    const { data, error } = await supabase
      .from("conversations")
      .select("*")
      .eq("user_id", userId)
      .order("created_at", { ascending: false });

    if (error) console.error("Conversations fetch error:", error.message);
    if (data) setConversations(data);
  };

  // Direct Click Handler for Previous Chat
  const selectChat = (chatId) => {
    console.log("Selecting chat ID:", chatId);
    setActiveChat(chatId);
  };

  const createNewChat = () => {
    setActiveChat(null);
    setMessages([]);
  };

  const deleteConversation = async (e, id) => {
    e.stopPropagation();
    await supabase.from("conversations").delete().eq("id", id);
    setConversations((prev) => prev.filter((c) => c.id !== id));
    if (activeChat === id) {
      setActiveChat(null);
      setMessages([]);
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    router.push("/login");
  };

  // Safe Text Extractor for PDF and Text files
  const handleFileChange = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    setSelectedFile(file);
    setReadingFile(true);

    try {
      let extractedText = "";

      if (file.type === "application/pdf" || file.name.endsWith(".pdf")) {
        const arrayBuffer = await file.arrayBuffer();
        const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;

        let fullText = "";
        for (let i = 1; i <= pdf.numPages; i++) {
          const page = await pdf.getPage(i);
          const textContent = await page.getTextContent();
          const pageText = textContent.items.map((item) => item.str).join(" ");
          fullText += pageText + "\n";
        }
        extractedText = fullText;
      } else {
        extractedText = await file.text();
      }

      const truncatedText = extractedText.slice(0, 12000);
      setFileContent(truncatedText);
    } catch (err) {
      alert("Error reading file: " + err.message);
      removeFile();
    } finally {
      setReadingFile(false);
    }
  };

  const removeFile = () => {
    setSelectedFile(null);
    setFileContent("");
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

 async function sendMessage(e) {
    e?.preventDefault();

    let text = input.trim();
    if ((!text && !selectedFile) || loading || imageLoading || readingFile) return;

    const displayUserContent = selectedFile
      ? `📎 [File: ${selectedFile.name}]\n${text}`
      : text;

    const payloadPrompt = selectedFile
      ? `[Attached File: ${selectedFile.name}]\n\nFile Content:\n${fileContent}\n\nUser Question: ${text || "Please review and analyze this file."}`
      : text;

    let currentChatId = activeChat;

    // Fix 1: If activeChat doesn't exist, create it first and ensure currentChatId gets valid ID
    if (!currentChatId) {
      const titleText = selectedFile ? `📎 ${selectedFile.name}` : text.slice(0, 30);
      const { data, error } = await supabase
        .from("conversations")
        .insert({ user_id: user.id, title: titleText })
        .select()
        .single();

      if (error) {
        console.error("Error creating conversation:", error.message);
        return;
      }

      if (data) {
        currentChatId = data.id;
        setActiveChat(data.id);
        setConversations((prev) => [data, ...prev]);
      }
    }

    const next = [...messages, { role: "user", content: displayUserContent }];
    setMessages(next);
    setInput("");
    removeFile();
    setLoading(true);

    // Fix 2: Always save user message using reliable currentChatId variable
    const { error: userMsgError } = await supabase.from("messages").insert({
      conversation_id: currentChatId,
      role: "user",
      content: displayUserContent,
      type: "text",
    });

    if (userMsgError) {
      console.error("Error inserting user message:", userMsgError.message);
    }

    abortControllerRef.current = new AbortController();

    try {
      const apiMessages = messages.map((m) => ({
        role: m.role,
        content: m.content,
      }));
      apiMessages.push({ role: "user", content: payloadPrompt });

      const res = await fetch("/api/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ messages: apiMessages }),
        signal: abortControllerRef.current.signal,
      });

      const data = await res.json();

      if (!res.ok) {
        throw new Error(data.error || "Request failed");
      }

      const assistantResponse = data.message || "No response content";

      setMessages([
        ...next,
        {
          role: "assistant",
          content: assistantResponse,
          type: "text",
        },
      ]);

      // Fix 3: Save Assistant response using reliable currentChatId variable
      const { error: aiMsgError } = await supabase.from("messages").insert({
        conversation_id: currentChatId,
        role: "assistant",
        content: assistantResponse,
        type: "text",
      });

      if (aiMsgError) {
        console.error("Error inserting AI response:", aiMsgError.message);
      }

    } catch (err) {
      if (err.name === "AbortError") {
        setMessages((prev) => [
          ...prev,
          { role: "assistant", content: "Response stopped" },
        ]);
      } else {
        setMessages([
          ...next,
          {
            role: "assistant",
            content: "Error: " + err.message,
          },
        ]);
      }
    } finally {
      setLoading(false);
    }
  }

  async function generateImage(e) {
    e?.preventDefault();

    const text = input.trim();
    if (!text || loading || imageLoading) return;

    let chatId = activeChat;

    if (!chatId) {
      const { data } = await supabase
        .from("conversations")
        .insert({ user_id: user.id, title: "🖼️ " + text.slice(0, 25) })
        .select()
        .single();

      if (data) {
        chatId = data.id;
        setActiveChat(data.id);
        setConversations([data, ...conversations]);
      }
    }

    const next = [
      ...messages,
      {
        role: "user",
        content: "🖼️ Generate image: " + text,
      },
    ];

    setMessages(next);
    setInput("");
    setImageLoading(true);

    if (chatId) {
      await supabase.from("messages").insert({
        conversation_id: chatId,
        role: "user",
        content: "🖼️ Generate image: " + text,
        type: "text",
      });
    }

    abortControllerRef.current = new AbortController();

    try {
      const res = await fetch("/api/image", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ prompt: text }),
        signal: abortControllerRef.current.signal,
      });

      const data = await res.json();

      if (!res.ok) {
        throw new Error(data.error || "Image generation failed");
      }

      setMessages([
        ...next,
        {
          role: "assistant",
          type: "image",
          content: data.url || data.image,
        },
      ]);

      if (chatId) {
        await supabase.from("messages").insert({
          conversation_id: chatId,
          role: "assistant",
          content: data.url || data.image,
          type: "image",
        });
      }
    } catch (err) {
      if (err.name === "AbortError") {
        setMessages((prev) => [
          ...prev,
          { role: "assistant", content: "Response stopped" },
        ]);
      } else {
        setMessages([
          ...next,
          {
            role: "assistant",
            content: "Image Error: " + err.message,
          },
        ]);
      }
    } finally {
      setImageLoading(false);
    }
  }

  const stopResponse = () => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
      setLoading(false);
      setImageLoading(false);
    }
  };

  return (
    <main className="shell">
      <aside className="sidebar">
        <div className="sidebarHeader">
          <div className="brand">MY AI</div>
          <button className="themeToggle" onClick={toggleTheme}>
            {theme === "dark" ? "☀️ Light" : "🌙 Dark"}
          </button>
        </div>

        <button className="newChat" onClick={createNewChat}>
          <span>+</span> New chat
        </button>

        <div className="conversationsList">
          {conversations.map((chat) => (
            <div
              key={chat.id}
              onClick={() => selectChat(chat.id)}
              className={`chatItem ${activeChat === chat.id ? "active" : ""}`}
            >
              <span style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                💬 {chat.title}
              </span>
              <button
                className="chatDeleteBtn"
                onClick={(e) => deleteConversation(e, chat.id)}
                title="Delete Chat"
              >
                ✕
              </button>
            </div>
          ))}
        </div>

        <div className="sidebarFooter">
          <div className="userProfile">
            <div className="userAvatar">
              {user?.email?.charAt(0).toUpperCase() || "U"}
            </div>
            <span className="userName">
              {user?.email?.split("@")[0] || "User"}
            </span>
          </div>
          <button className="logoutBtn" onClick={handleLogout}>
            Logout
          </button>
        </div>
      </aside>

      <section className="chat">
        <header className="topbar">
          <strong>My AI</strong>
          <span>GPT-4o Mini</span>
        </header>

        <div className="messages">
          {messages.length === 0 ? (
            <div className="welcome">
              <h1>How can I help?</h1>
              <p>Ask anything, upload a file to analyze, or generate an image.</p>
            </div>
          ) : (
            messages.map((m, i) => (
              <div className={"row " + m.role} key={i}>
                <div className="bubble">
                  {m.type === "image" ? (
                    <img
                      src={m.content}
                      alt="Generated image"
                      style={{
                        maxWidth: "100%",
                        width: "700px",
                        borderRadius: "14px",
                        display: "block",
                      }}
                    />
                  ) : (
                    <span style={{ whiteSpace: "pre-wrap" }}>{m.content}</span>
                  )}
                </div>
              </div>
            ))
          )}

          {(loading || imageLoading) && (
            <div className="row assistant">
              <div className="bubble">
                {imageLoading ? "Creating your image…" : "Analyzing & Thinking…"}
              </div>
            </div>
          )}
        </div>

        <div className="composerContainer">
          {selectedFile && (
            <div
              style={{
                padding: "8px 16px",
                backgroundColor: "var(--hover-bg)",
                color: "var(--accent-color)",
                borderRadius: "8px",
                marginBottom: "8px",
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
              }}
            >
              <span style={{ fontSize: "14px" }}>
                📎 Attached: <strong>{selectedFile.name}</strong>{" "}
                {readingFile ? "(Extracting text...)" : ""}
              </span>
              <button
                onClick={removeFile}
                style={{
                  background: "none",
                  border: "none",
                  color: "#ff4d4d",
                  cursor: "pointer",
                  fontWeight: "bold",
                }}
              >
                ✕
              </button>
            </div>
          )}

          <form className="composer" onSubmit={sendMessage}>
            <input
              type="file"
              ref={fileInputRef}
              onChange={handleFileChange}
              style={{ display: "none" }}
              accept=".pdf,.txt,.js,.jsx,.ts,.tsx,.json,.csv,.md,.css,.html"
            />

            <button
              type="button"
              onClick={() => fileInputRef.current?.click()}
              disabled={loading || imageLoading || readingFile}
              title="Upload File"
            >
              📎
            </button>

            <input
              value={input}
              onChange={(e) => setInput(e.target.value)}
              placeholder="Message My AI or ask about uploaded file..."
              disabled={loading || imageLoading || readingFile}
            />

            <button
              type="button"
              onClick={generateImage}
              disabled={loading || imageLoading || !input.trim()}
              title="Generate image"
            >
              🖼️
            </button>

            {loading || imageLoading ? (
              <button
                type="button"
                onClick={stopResponse}
                title="Stop response"
                style={{ background: "#ff4d4d", color: "#fff" }}
              >
                🛑
              </button>
            ) : (
              <button
                type="submit"
                disabled={(!input.trim() && !selectedFile) || readingFile}
                title="Send message"
              >
                ↑
              </button>
            )}
          </form>

          <div className="notice">
            AI can make mistakes. Check important information.
          </div>
        </div>
      </section>
    </main>
  );
}